CREATE TABLE events (
    id INTEGER PRIMARY KEY,
    test_run_id INTEGER REFERENCES test_runs(id) ON DELETE RESTRICT,
    source_artifact_id INTEGER NOT NULL REFERENCES source_artifacts(id) ON DELETE RESTRICT,
    timestamp TEXT,
    category TEXT NOT NULL CHECK (length(trim(category)) > 0),
    component TEXT,
    event_type TEXT,
    message TEXT NOT NULL CHECK (length(trim(message)) > 0),
    source_line INTEGER CHECK (source_line IS NULL OR (typeof(source_line) = 'integer' AND source_line > 0)),
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE evidence_links (
    id INTEGER PRIMARY KEY,
    finding_id INTEGER REFERENCES findings(id) ON DELETE RESTRICT CHECK (finding_id > 0),
    unknown_id INTEGER REFERENCES unknowns(id) ON DELETE RESTRICT CHECK (unknown_id > 0),
    decision_id INTEGER REFERENCES decisions(id) ON DELETE RESTRICT CHECK (decision_id > 0),
    test_run_id INTEGER REFERENCES test_runs(id) ON DELETE RESTRICT CHECK (test_run_id > 0),
    event_id INTEGER REFERENCES events(id) ON DELETE RESTRICT CHECK (event_id > 0),
    error_id INTEGER REFERENCES errors(id) ON DELETE RESTRICT CHECK (error_id > 0),
    entity_id INTEGER REFERENCES entities(id) ON DELETE RESTRICT CHECK (entity_id > 0),
    relationship_id INTEGER REFERENCES relationships(id) ON DELETE RESTRICT CHECK (relationship_id > 0),
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    CHECK ((finding_id IS NOT NULL) + (unknown_id IS NOT NULL) + (decision_id IS NOT NULL) = 1),
    CHECK ((test_run_id IS NOT NULL) + (event_id IS NOT NULL) + (error_id IS NOT NULL)
           + (entity_id IS NOT NULL) + (relationship_id IS NOT NULL) = 1)
);
CREATE TABLE experiment_symbols (
    id INTEGER PRIMARY KEY,
    experiment_id INTEGER NOT NULL REFERENCES experiments(id) ON DELETE RESTRICT,
    symbol TEXT NOT NULL CHECK (length(trim(symbol)) > 0)
);
CREATE TABLE experiments (
    id INTEGER PRIMARY KEY,
    question TEXT NOT NULL CHECK (length(trim(question)) > 0),
    observed_result TEXT NOT NULL CHECK (length(trim(observed_result)) > 0),
    source_artifact_id INTEGER REFERENCES source_artifacts(id) ON DELETE RESTRICT,
    test_run_id INTEGER REFERENCES test_runs(id) ON DELETE RESTRICT,
    mod_build TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE findings (
    id INTEGER PRIMARY KEY,
    subject_entity_id INTEGER REFERENCES entities(id) ON DELETE RESTRICT,
    subject_text TEXT,
    finding TEXT NOT NULL CHECK (length(trim(finding)) > 0),
    confidence TEXT NOT NULL DEFAULT 'unknown' CHECK (confidence IN ('confirmed', 'strong', 'tentative', 'unknown')),
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'superseded', 'disproven')),
    source_artifact_id INTEGER REFERENCES source_artifacts(id) ON DELETE RESTRICT,
    test_run_id INTEGER REFERENCES test_runs(id) ON DELETE RESTRICT,
    source_line INTEGER CHECK (source_line IS NULL OR (typeof(source_line) = 'integer' AND source_line > 0)),
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), superseded_by_finding_id INTEGER REFERENCES findings(id) ON DELETE RESTRICT CHECK (superseded_by_finding_id IS NULL OR superseded_by_finding_id <> id) CHECK (superseded_by_finding_id IS NULL OR status = 'superseded'),
    CHECK (source_line IS NULL OR source_artifact_id IS NOT NULL)
);
CREATE TABLE relationships (
    id INTEGER PRIMARY KEY,
    source_entity_id INTEGER NOT NULL REFERENCES entities(id) ON DELETE RESTRICT,
    relationship_type TEXT NOT NULL CHECK (length(trim(relationship_type)) > 0),
    target_entity_id INTEGER NOT NULL REFERENCES entities(id) ON DELETE RESTRICT,
    source_artifact_id INTEGER REFERENCES source_artifacts(id) ON DELETE RESTRICT,
    test_run_id INTEGER REFERENCES test_runs(id) ON DELETE RESTRICT,
    notes TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE schema_metadata (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    schema_version INTEGER NOT NULL CHECK (schema_version >= 1),
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE source_artifacts (
    id INTEGER PRIMARY KEY,
    artifact_type TEXT NOT NULL CHECK (artifact_type IN
        ('log', 'source_code', 'assembly', 'decompiler_export', 'research_note', 'manual_observation', 'other')),
    path TEXT NOT NULL CHECK (length(trim(path)) > 0),
    filename TEXT NOT NULL CHECK (length(trim(filename)) > 0),
    sha256 TEXT CHECK (sha256 IS NULL OR
        (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-fA-F]*')),
    created_at TEXT,
    imported_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    notes TEXT
);
CREATE TABLE test_runs (
    id INTEGER PRIMARY KEY,
    source_artifact_id INTEGER REFERENCES source_artifacts(id) ON DELETE RESTRICT,
    started_at TEXT,
    profile TEXT,
    game_build TEXT,
    mod_build TEXT,
    result TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK (result IN
        ('PASS', 'NEEDS_ATTENTION', 'FAIL', 'INCOMPLETE', 'UNKNOWN')),
    notes TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE unknowns (
    id INTEGER PRIMARY KEY,
    subject_entity_id INTEGER REFERENCES entities(id) ON DELETE RESTRICT,
    question TEXT NOT NULL CHECK (length(trim(question)) > 0),
    importance TEXT NOT NULL DEFAULT 'medium' CHECK (importance IN ('low', 'medium', 'high', 'critical')),
    status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'investigating', 'resolved', 'blocked')),
    required_evidence TEXT,
    related_feature TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    resolved_at TEXT
);
CREATE INDEX idx_source_artifacts_sha256 ON source_artifacts (sha256);
CREATE INDEX idx_source_artifacts_type_path ON source_artifacts (artifact_type, path);
CREATE INDEX idx_test_runs_artifact ON test_runs (source_artifact_id);
CREATE INDEX idx_test_runs_started_at ON test_runs (started_at);
CREATE INDEX idx_events_run_timestamp ON events (test_run_id, timestamp);
CREATE INDEX idx_events_artifact_line ON events (source_artifact_id, source_line);
CREATE INDEX idx_events_category_type ON events (category, event_type);
CREATE INDEX idx_errors_run_timestamp ON errors (test_run_id, timestamp);
CREATE INDEX idx_errors_artifact_line ON errors (source_artifact_id, source_line);
CREATE INDEX idx_errors_severity ON errors (severity);
CREATE INDEX idx_entities_type_name ON entities (entity_type, name);
CREATE INDEX idx_entities_canonical_name ON entities (canonical_name);
CREATE INDEX idx_findings_subject ON findings (subject_entity_id);
CREATE INDEX idx_findings_artifact_line ON findings (source_artifact_id, source_line);
CREATE INDEX idx_findings_run ON findings (test_run_id);
CREATE INDEX idx_findings_status_confidence ON findings (status, confidence);
CREATE INDEX idx_unknowns_subject ON unknowns (subject_entity_id);
CREATE INDEX idx_unknowns_status_importance ON unknowns (status, importance);
CREATE INDEX idx_decisions_subject ON decisions (subject_entity_id);
CREATE INDEX idx_decisions_finding ON decisions (finding_id);
CREATE INDEX idx_decisions_status ON decisions (status);
CREATE INDEX idx_relationships_source_type ON relationships (source_entity_id, relationship_type);
CREATE INDEX idx_relationships_target ON relationships (target_entity_id);
CREATE INDEX idx_relationships_artifact ON relationships (source_artifact_id);
CREATE INDEX idx_relationships_run ON relationships (test_run_id);
CREATE UNIQUE INDEX idx_evidence_links_pair ON evidence_links (
    ifnull(finding_id, 0), ifnull(unknown_id, 0), ifnull(decision_id, 0),
    ifnull(test_run_id, 0), ifnull(event_id, 0), ifnull(error_id, 0),
    ifnull(entity_id, 0), ifnull(relationship_id, 0)
);
CREATE INDEX idx_evidence_links_finding ON evidence_links (finding_id);
CREATE INDEX idx_evidence_links_unknown ON evidence_links (unknown_id);
CREATE INDEX idx_evidence_links_decision ON evidence_links (decision_id);
CREATE INDEX idx_evidence_links_run ON evidence_links (test_run_id);
CREATE INDEX idx_evidence_links_event ON evidence_links (event_id);
CREATE INDEX idx_evidence_links_error ON evidence_links (error_id);
CREATE INDEX idx_evidence_links_entity ON evidence_links (entity_id);
CREATE INDEX idx_evidence_links_relationship ON evidence_links (relationship_id);
CREATE TRIGGER events_fts_ai AFTER INSERT ON events BEGIN
    VALUES (new.id, new.message, new.component, new.category, new.event_type);
END;
CREATE TRIGGER events_fts_ad AFTER DELETE ON events BEGIN
    VALUES ('delete', old.id, old.message, old.component, old.category, old.event_type);
END;
CREATE TRIGGER events_fts_au AFTER UPDATE ON events BEGIN
    VALUES ('delete', old.id, old.message, old.component, old.category, old.event_type);
    VALUES (new.id, new.message, new.component, new.category, new.event_type);
END;
CREATE TRIGGER errors_fts_ai AFTER INSERT ON errors BEGIN
    VALUES (new.id, new.message, new.component, new.stack_trace);
END;
CREATE TRIGGER errors_fts_ad AFTER DELETE ON errors BEGIN
    VALUES ('delete', old.id, old.message, old.component, old.stack_trace);
END;
CREATE TRIGGER errors_fts_au AFTER UPDATE ON errors BEGIN
    VALUES ('delete', old.id, old.message, old.component, old.stack_trace);
    VALUES (new.id, new.message, new.component, new.stack_trace);
END;
CREATE INDEX idx_experiments_artifact ON experiments (source_artifact_id);
CREATE INDEX idx_experiments_run ON experiments (test_run_id);
CREATE INDEX idx_experiment_symbols_symbol ON experiment_symbols (symbol);
CREATE INDEX idx_experiment_symbols_experiment ON experiment_symbols (experiment_id);
CREATE INDEX idx_findings_superseded_by ON findings (superseded_by_finding_id);
COMMIT;
